const Search={index:null,async buildIndex(){this.index={customers:[],appointments:[],orders:[]};const e=await DB.getAllCustomers();this.index.customers=await Promise.all(e.map(async e=>{const t=e;return{id:t.id,type:"customer",title:`${t.firstName} ${t.lastName}`,subtitle:t.address?`${t.address.line1}, ${t.address.postcodeFormatted}`:"",phone:t.phone,customerNumber:t.customerNumber,keywords:[t.firstName,t.lastName,t.phone,t.email,t.customerNumber,t.address?.line1,t.address?.postcode,t.address?.city].filter(Boolean).join(" ").toLowerCase()}}));const t=await DB.db.appointments.toArray();this.index.appointments=t.map(e=>({id:e.id,type:"appointment",title:`${Utils.formatDate(e.date,"short")} ${Utils.formatTime(e.date)}`,subtitle:e.type,keywords:[e.type,e.status,e.outcome,Utils.formatDate(e.date)].filter(Boolean).join(" ").toLowerCase()}));const s=await DB.db.orders.toArray();this.index.orders=s.map(e=>({id:e.id,type:"order",title:e.orderNumber,subtitle:e.supplierOrderNumber||"",keywords:[e.orderNumber,e.supplierOrderNumber,e.status].filter(Boolean).join(" ").toLowerCase()}))},async search(e,t={}){if(!e||e.trim().length<2)return[];const s=e.toLowerCase().trim(),r=[];if(!t.types||t.types.includes("customer"))try{const e=await DB.searchCustomers(s);r.push(...e.map(e=>({type:"customer",id:e.id,title:`${e.firstName} ${e.lastName}`,subtitle:e.customerNumber,detail:e.address?`${e.address.line1}${e.address.postcode?", "+e.address.postcode:""}`:"",icon:"person",data:e})))}catch(e){console.error("Customer search failed:",e)}if(!t.types||t.types.includes("appointment"))try{const e=new Set(r.filter(e=>"customer"===e.type).map(e=>e.id)),t=await DB.db.appointments.filter(t=>e.has(t.customerId)||t.notes&&t.notes.toLowerCase().includes(s)).limit(10).toArray(),a=[...new Set(t.map(e=>e.customerId))],o=new Map;if(a.length){const e=await DB.getCustomersByIds(a);for(const t of e)t&&o.set(t.id,t)}for(const e of t){const t=o.get(e.customerId);r.push({type:"appointment",id:e.id,title:`${Utils.formatDate(e.date,"short")} — ${Utils.formatTime(e.date)}`,subtitle:t?`${t.firstName} ${t.lastName}`:"Unknown",detail:CONFIG.appointmentTypes.find(t=>t.id===e.type)?.name||e.type,icon:"event",data:e})}}catch(e){console.error("Appointment search failed:",e)}if(!t.types||t.types.includes("order"))try{const e=await DB.db.orders.filter(e=>(e.orderNumber||"").toLowerCase().startsWith(s)||(e.supplierOrderNumber||"").toLowerCase().startsWith(s)).limit(10).toArray(),t=[...new Set(e.map(e=>e.customerId))],a=new Map;if(t.length){const e=await DB.getCustomersByIds(t);for(const t of e)t&&a.set(t.id,t)}for(const t of e){const e=a.get(t.customerId);r.push({type:"order",id:t.id,title:t.orderNumber,subtitle:e?`${e.firstName} ${e.lastName}`:"Unknown",detail:`£${t.total}`,icon:"receipt",data:t})}}catch(e){console.error("Order search failed:",e)}return r.slice(0,t.limit||20)},async searchByPostcode(e){const t=Utils.normalizePostcode(e);return await DB.db.customers.where("postcodeNormalized").startsWith(t).limit(20).toArray()},searchNearby:async(e,t,s=10)=>(await DB.getAllCustomers()).filter(r=>!!r.address?.latLng&&Geo.calculateDistance(e,t,r.address.latLng[0],r.address.latLng[1])<=s).map(s=>({...s,distance:Geo.calculateDistance(e,t,s.address.latLng[0],s.address.latLng[1])})).sort((e,t)=>e.distance-t.distance)};
